import {PETS,GRADES,MATERIALS,amount,canMaterials} from './economy.mjs?v=0.5';
import {REGIONS,regionUnlocked} from './regions.mjs?v=0.5';
import {MOUNTS,PET_EFFECTS,SKILL_NAMES,ensureCompanions,mountCost,mountReady,mountSpeed,skillProfile} from './companions.mjs?v=0.5';
import {BRANCHES,cost,stats} from './engine.mjs?v=0.5';
let pet=null,mount=null;
const labels={hp:'HP',mp:'Linh lực',atk:'Công',def:'Thủ'},paths={balanced:'Cân bằng',power:'Uy lực · hiệu quả +20%',swift:'Lưu chuyển · hồi chiêu −25%'};
export function renderCompanions(which,c){if(!['pets','mounts','skills'].includes(which))return false;const {game,openModal,closeModal,showPanel,save,hud}=c,s=game.s;ensureCompanions(s);const state=s.companions,$=q=>document.querySelector(q),$$=q=>[...document.querySelectorAll(q)],refresh=()=>{hud();save();showPanel(which);};
 const badge=g=>`<span class="grade-tag rarity-${g}">${GRADES[g].color} · ${GRADES[g].name}</span>`;
 const price=(materials,g)=>Object.entries(materials).map(([k,n])=>`${n} ${MATERIALS[k].name} (có ${amount(s,k,g)})`).join(' + ');
 const stage=title=>`<section class="avatar-stage"><h3>${title}</h3><canvas id="avatarCanvas" aria-label="Mô hình 3D ${title}"></canvas><div class="avatar-controls"><button id="avatarLeft">↶</button><span>Kéo để xoay 360°</span><button id="avatarRight">↷</button></div></section>`;
 let body='',preview=s;
 if(which==='pets'){
 pet??=s.spirit;const p=PETS[pet],lv=s.petLevels[pet],tr=state.treasures[pet],gold=100+lv*90,tm={gem:3*(tr+1),essence:2*(tr+1)};preview={...s,previewCreature:p.shape};
 body=`<p>Một pet đồng hành. Chỉ pet được chọn cộng chỉ số và dùng kỹ năng; xem mẫu không tự triển khai.</p><div class="companion-layout">${stage(p.name)}<section><h3>${p.name} · Bậc ${lv}/5</h3>${badge(p.grade)}<p>${PET_EFFECTS[pet]} Nhịp 3 giây, phạm vi 12m.</p><p>Chỉ số đang có: ${Object.entries(p.bonus).map(([k,n])=>`${labels[k]} +${Math.round(n*lv*(1+tr*.1))}`).join(' · ')}</p><p>${regionUnlocked(s,p.unlock)?'Đã mở khu vực':REGIONS[p.unlock].unlockText}</p><p>${gold} đồng + ${lv+2} Linh phách ${GRADES[p.grade].color} (có ${amount(s,'essence',p.grade)}).</p><div class="toolbar"><button id="petRaise" ${lv>=5||!regionUnlocked(s,p.unlock)||s.gold<gold||amount(s,'essence',p.grade)<lv+2?'disabled':''}>${lv?'Nuôi dưỡng lên bậc '+(lv+1):'Triệu hồi'}</button><button id="petDeploy" ${!lv||s.spirit===pet?'disabled':''}>${s.spirit===pet&&lv?'Đang đồng hành':'Triển khai pet'}</button></div><h4>Bảo vật linh châu · ${tr}/3</h4><p>Mỗi cấp tăng 10% chỉ số pet; thêm sức mạnh cho kỹ năng riêng. Cố định theo pet, không giao dịch.</p><p>${tr===3?'Đã tối đa':120*(tr+1)+' đồng + '+price(tm,p.grade)+' · cùng màu pet'}</p><button id="petTreasure" ${!lv||tr>=3||s.gold<120*(tr+1)||!canMaterials(s,tm,p.grade)?'disabled':''}>Nâng bảo vật</button><h4>Hành vi pet đang triển khai</h4><select id="petStance" aria-label="Hành vi pet">${Object.entries({aggressive:'Chủ động — tấn công quái trong 12m',defend:'Bảo vệ — chỉ đánh quái sát chủ hoặc đang ra đòn',passive:'Đi theo — giữ chỉ số, tắt kỹ năng pet'}).map(([k,n])=>`<option value="${k}" ${state.stance===k?'selected':''}>${n}</option>`).join('')}</select><p class="subtext">Hạc/lộc hồi phục trong hai chế độ đầu; Huyền quy tạo hộ thân khi có địch. Đi theo tắt cả hồi phục và hộ thân.</p></section></div><div class="companion-roster">${Object.entries(PETS).map(([k,p])=>`<button class="rarity-${p.grade} ${pet===k?'active':''}" data-pet-view="${k}"><span>${p.icon}</span><b>${p.name}</b><small>Bậc ${s.petLevels[k]}/5 · ${s.spirit===k&&s.petLevels[k]?'Đồng hành':s.petLevels[k]?'Đã có':'Chưa triệu hồi'}</small></button>`).join('')}</div>`;
 }else if(which==='mounts'){
 mount??=state.mount;const m=MOUNTS[mount],lv=state.mountLevels[mount],r=mountCost(s,mount),ready=mountReady(s,mount);preview={...s,previewCreature:m.shape,previewRide:true};
 body=`<p>Chọn thú cưỡi để đổi ngoại hình và tốc độ. Nhấn V lên/xuống; tấn công hoặc thu thập sẽ xuống thú. Long thú di chuyển trên mặt đất.</p><div class="companion-layout">${stage(m.name)}<section><h3>${m.name} · Huấn luyện ${lv}/5</h3>${badge(m.grade)}<p>${ready?'Đã mở':s.quest<6?'Hoàn thành nhiệm vụ 6 Vân Sơn để mở thú cưỡi.':REGIONS[m.unlock].unlockText}</p><p>Tốc độ bậc ${Math.max(1,lv)}: ${(m.speed+Math.max(0,lv-1)*.6).toFixed(1)} m/s. Đi bộ: 7,3 m/s.</p><p>HP khi chọn: +${lv?(lv-1)*12+m.grade*10:0}. Chỉ thú được chọn cộng HP, kể cả khi đã xuống.</p><p>${mount==='deer'?'Linh lộc bậc 1 được tặng; mở quyền cưỡi sau nhiệm vụ 6.':''}</p><p>${lv===5?'Đã đạt cấp tối đa':r.gold+' đồng + '+price(r.materials,m.grade)+' · '+GRADES[m.grade].color}</p><div class="toolbar"><button id="mountRaise" ${!ready||lv>=5||s.gold<r.gold||!canMaterials(s,r.materials,m.grade)?'disabled':''}>${lv?'Huấn luyện lên '+(lv+1):'Thuần phục'}</button><button id="mountSelect" ${!ready||!lv||state.mount===mount?'disabled':''}>${state.mount===mount?'Đang chọn':'Chọn thú cưỡi'}</button><button id="mountRide" ${!ready||!lv?'disabled':''}>${game.mount&&state.mount===mount?'Xuống thú':'Cưỡi thú này · V'}</button></div><p>Thú đang chọn: ${MOUNTS[state.mount].name} · ${mountSpeed(s).toFixed(1)} m/s.</p></section></div><div class="companion-roster">${Object.entries(MOUNTS).map(([k,m])=>`<button data-mount-view="${k}" class="rarity-${m.grade} ${mount===k?'active':''}"><span>${m.icon}</span><b>${m.name}</b><small>Bậc ${state.mountLevels[k]}/5 · ${state.mount===k?'Đang chọn':state.mountLevels[k]?'Đã có':'Chưa có'}</small></button>`).join('')}</div>`;
 }else{
 body=`<p>Kỹ năng chung của ba lớp, hiệu quả dựa trên chỉ số nhân vật. Phím 2/Q, 3, 4; Lướt dùng Shift. Auto chỉ dùng các kỹ năng được bật, thao tác tay luôn dùng được.</p><div class="skill-cards">${Object.entries(SKILL_NAMES).map(([k,n],i)=>{const lv=s.upgrades[k],p=skillProfile(s,k),r=cost(s,k),before=stats(s),next=skillProfile({...s,upgrades:{...s.upgrades,[k]:Math.min(5,lv+1)}},k),effect=x=>k==='mend'?Math.round(before.hp*x.heal)+' HP':Math.round(before.atk*x.multiplier)+' sát thương'+(k==='nova'?' · choáng '+x.stun.toFixed(2)+'s':'');return `<article class="skill-detail"><span class="skill-glyph">${BRANCHES[k].icon}</span><h3>${n} · Bậc ${lv}/5</h3><p>Phím ${i+2}${i===0?' / Q':''} · ${p.mp} MP · hồi ${p.cooldown.toFixed(2)}s</p><p>Hiện tại: <b>${effect(p)}</b></p><p>${lv===5?'Đã tối đa':'Bậc sau: '+effect(next)}</p><p>${lv===5?'':r.gold+' đồng + '+price({[BRANCHES[k].resource]:r[BRANCHES[k].resource]},0)+' · Trắng'}</p><button data-skill-up="${k}" ${lv>=5||s.quest<BRANCHES[k].unlock||!game.canPay(r)?'disabled':''}>Nâng kỹ năng</button>${s.quest<BRANCHES[k].unlock?'<p>Mở nâng cấp sau nhiệm vụ '+BRANCHES[k].unlock+'.</p>':''}<h4>Chuyên hóa · đổi miễn phí từ bậc 2</h4><select data-skill-path="${k}" aria-label="Chuyên hóa ${n}" ${lv<2?'disabled':''}>${Object.entries(paths).map(([id,label])=>`<option value="${id}" ${state.skillPaths[k]===id?'selected':''}>${label}</option>`).join('')}</select><p class="subtext">Uy lực tăng sát thương/hồi HP; Lưu chuyển giảm hồi chiêu. Thay nhánh không xóa hồi chiêu đang chạy.</p><label><input type="checkbox" data-skill-auto="${k}" ${state.autoSkills[k]?'checked':''}> Dùng ${n} khi auto</label></article>`;}).join('')}</div><label class="select-line"><input type="checkbox" data-skill-auto="dash" ${state.autoSkills.dash?'checked':''}> Tự lướt né đòn khi auto (4 giây hồi, 0 MP)</label>`;
 }
 openModal(`<span class="eyebrow">LONG MẠCH · ĐỒNG HÀNH & VÕ HỌC</span><h2>${{pets:'Linh thú đồng hành',mounts:'Thú cưỡi',skills:'Võ học & chuyên hóa'}[which]}</h2><div class="panel-tabs">${Object.entries({pets:'Pet · P',mounts:'Thú cưỡi · U',skills:'Kỹ năng · L',loadout:'Nhân vật',materials:'Nguyên liệu',atlas:'Thế giới'}).map(([k,n])=>`<button data-comp-nav="${k}" class="${k===which?'active':''}">${n}</button>`).join('')}</div>${body}`,which,preview);
 $$('[data-comp-nav]').forEach(b=>b.onclick=()=>showPanel(b.dataset.compNav));$$('[data-pet-view]').forEach(b=>b.onclick=()=>{pet=b.dataset.petView;showPanel(which);$('#modal').scrollTop=0;});$$('[data-mount-view]').forEach(b=>b.onclick=()=>{mount=b.dataset.mountView;showPanel(which);$('#modal').scrollTop=0;});
 $('#petRaise')?.addEventListener('click',()=>{const active=s.spirit;game.upgradePet(pet);s.spirit=active;refresh();});$('#petDeploy')?.addEventListener('click',()=>{game.choosePet(pet);game.spiritClock=0;refresh();});$('#petTreasure')?.addEventListener('click',()=>{game.upgradeTreasure(pet);refresh();});$('#petStance')?.addEventListener('change',e=>{game.setPetStance(e.target.value);refresh();});
 $('#mountRaise')?.addEventListener('click',()=>{game.upgradeMount(mount);refresh();});$('#mountSelect')?.addEventListener('click',()=>{game.chooseMount(mount);refresh();});$('#mountRide')?.addEventListener('click',()=>{if(state.mount!==mount)game.chooseMount(mount);closeModal();game.toggleMount();save();hud();});
 $$('[data-skill-up]').forEach(b=>b.onclick=()=>{game.upgrade(b.dataset.skillUp);refresh();});$$('[data-skill-path]').forEach(b=>b.onchange=()=>{game.setSkillPath(b.dataset.skillPath,b.value);refresh();});$$('[data-skill-auto]').forEach(b=>b.onchange=()=>{game.setAutoSkill(b.dataset.skillAuto,b.checked);save();});return true;
}
